// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { IRouletteEngine } from "../interfaces/IRouletteEngine.sol";

/// @title SideBetRoundLib — load consecutive global-round outcomes for side-bet evaluation.
library SideBetRoundLib {
    /// @dev Returns observed spins for rounds `[startRound, startRound + count - 1]` and whether all are VRF-fulfilled.
    function loadWindow(
        IRouletteEngine engine,
        uint64 startRound,
        uint256 count
    ) internal view returns (uint8[] memory observed, bool allFulfilled) {
        if (count == 0) {
            return (new uint8[](0), true);
        }
        observed = new uint8[](count);
        allFulfilled = true;
        uint64 roundId = startRound;
        bool fulfilled;
        uint8 number;
        for (uint256 i; i < count; ) {
            (fulfilled, number) = engine.roundOutcome(roundId);
            if (!fulfilled) {
                allFulfilled = false;
                break;
            }
            observed[i] = number;
            unchecked {
                ++i;
                ++roundId;
            }
        }
    }

    /// @dev True when rounds `startRound .. startRound + windowSpins - 1` are all VRF-fulfilled.
    function windowFulfilled(IRouletteEngine engine, uint64 startRound, uint16 windowSpins) internal view returns (bool) {
        if (windowSpins == 0) return false;
        uint64 endRound = startRound + uint64(windowSpins) - 1;
        uint64 cur = engine.currentGlobalRound();
        if (endRound > cur) return false;
        bool fulfilled;
        if (endRound == cur) {
            (fulfilled, ) = engine.roundOutcome(cur);
            return fulfilled;
        }
        for (uint64 r = startRound; r <= endRound; ) {
            (fulfilled, ) = engine.roundOutcome(r);
            if (!fulfilled) return false;
            unchecked {
                ++r;
            }
        }
        return true;
    }

    /// @dev Win if any VRF-fulfilled round in `[startRound, startRound + windowSpins - 1]` had the jackpot drawn.
    function evaluateJackpotWindow(
        IRouletteEngine engine,
        uint64 startRound,
        uint16 windowSpins
    ) internal view returns (bool decided, bool won) {
        if (windowSpins == 0) return (false, false);

        uint64 endRound = startRound + uint64(windowSpins) - 1;
        uint64 cur = engine.currentGlobalRound();
        bool fulfilled;
        bool jackpot;
        for (uint64 r = startRound; r <= endRound; ) {
            if (r > cur) return (false, false);
            (fulfilled, jackpot) = engine.roundJackpotTriggered(r);
            if (!fulfilled) return (false, false);
            if (jackpot) return (true, true);
            unchecked {
                ++r;
            }
        }
        return (true, false);
    }
}

contracts/interfaces/IRouletteEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { IBankVault } from "./IBankVault.sol";

interface IRouletteEngine {
    /// @dev `TriggerVrf` locks the betting round and requests VRF in one job (single automation round-trip).
    enum JobKind {
        None,
        TriggerVrf,
        Payout
    }

    /// @notice For `JobKind.Payout`, `nextCursor` binds the roulette cursor while rows remain,
    /// then the jackpot cursor for lane-zero jackpot-only chunks. The tuple ABI is unchanged.
    /// `payoutShardIndex` is the automation lane and `payoutShardWidth` is `payoutParallelLaneCount`.
    /// Vault winners are sharded by global winner index (`index % width`); all lanes may service the same market.
    struct Job {
        JobKind kind;
        uint32 marketId;
        uint64 roundId;
        uint32 nextCursor;
        uint32 payoutShardIndex;
        uint32 payoutShardWidth;
    }

    /// @notice Registry-only market registration hook (e.g. `MarketRegistry.createMarket`).
    function registerMarketFromRegistry(uint32 marketId, address bank) external;

    function recordBet(
        uint32 marketId,
        address player,
        uint256 amount,
        bytes calldata betData,
        address referral
    ) external;

    function payoutParallelLaneCount() external view returns (uint32);

    /// @notice `payoutLane` is the automation lane id; `payoutShardWidth` must be zero (width is set on the returned job).
    function findNextJob(
        uint32 startCursor,
        uint32 scanLimit,
        uint32 payoutLane,
        uint32 payoutShardWidth
    ) external view returns (bool found, Job memory job);

    /// @notice Whether this automation lane should run `performUpkeep` for a `Payout` job (false = no on-chain tx).
    function payoutLaneHasWork(Job memory job) external view returns (bool);

    /// @notice Simulation-only: builds the exact payout rows for `checkUpkeep` (no storage writes).
    function previewPayoutBundle(Job memory job, uint32 maxPayoutsPerCall)
        external
        view
        returns (
            IBankVault.Payout[] memory winnerPayoutRows,
            address[] memory jackpotWinners,
            uint256[] memory jackpotAmounts
        );

    /// @notice Apply-only path for Automation: rows must match the latest `previewPayoutBundle` for `job` (trusted scheduler).
    /// @param winnerPayoutRows Vault winner rows from `previewPayoutBundle` (may be empty when only jackpot chunk applies).
    /// @param jackpotWinners BRB jackpot recipients from `previewPayoutBundle` (may be empty).
    /// @param jackpotAmounts BRB amounts aligned with `jackpotWinners`.
    function executeJob(
        Job memory job,
        IBankVault.Payout[] memory winnerPayoutRows,
        address[] memory jackpotWinners,
        uint256[] memory jackpotAmounts
    ) external returns (bool didWork);

    function currentGlobalRound() external view returns (uint64);

    function referrerOf(address player) external view returns (address);

    /// @notice Outcome for a completed global round (`vrfFulfilled` must be true before `winningNumber` is authoritative).
    function roundOutcome(uint64 roundId) external view returns (bool vrfFulfilled, uint8 winningNumber);

    /// @notice Jackpot draw flag for a global round (`jackpotTriggered` is authoritative only when `vrfFulfilled` is true).
    function roundJackpotTriggered(uint64 roundId) external view returns (bool vrfFulfilled, bool jackpotTriggered);

    function hasPendingVrf() external view returns (bool);

    function vrfActiveRound() external view returns (uint64);

    /// @notice Admin-only: request a new VRF for the current Settling round if the previous
    ///         request has been unanswered for 24 hours (Chainlink expiry). Fund the VRF subscription first.
    function retryVrf() external;

    /// @notice True while this market's global round is locked but not yet settled for that market (deposits / enqueue-withdraw blocked).
    function isBankLiquidityRestricted(uint32 marketId) external view returns (bool);

    /// @notice Free vault liquidity the market's open-round roulette liability still needs, beyond the
    /// stakes already locked. The vault deducts it before reserving liquidity for a side bet, so the
    /// two systems cannot commit the same tokens.
    function marketRouletteLiquidityNeed(uint32 marketId) external view returns (uint256);

    /// @notice Max withdrawal queue entries to finalize per settlement step for any bank (shared across markets).
    function withdrawalQueueBatchSize() external view returns (uint256);

    /// @notice Max pending withdrawal queue length per bank (shared cap across markets).
    function maxWithdrawalQueueLength() external view returns (uint256);
}

contracts/libraries/SideBetOutcomeLib.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { ISideBet } from "../interfaces/ISideBet.sol";

/// @title SideBetOutcomeLib — pure outcome evaluation for side bets.
/// @notice Evaluates a bet against the spins observed so far. Returns whether the bet can be
///         settled now (`decided`) and, if so, whether the player won. Win conditions resolve
///         early as soon as they are met; losses are only final once the full window is observed
///         (or once a win is provably impossible for RED_RATIO).
library SideBetOutcomeLib {
    uint256 private constant BPS_DENOMINATOR = 10_000;

    /// @dev European single-zero wheel red pockets. Matches `RouletteBetLib._isRedNumber`.
    function isRed(uint8 num) internal pure returns (bool) {
        return (num == 1 ||
            num == 3 ||
            num == 5 ||
            num == 7 ||
            num == 9 ||
            num == 12 ||
            num == 14 ||
            num == 16 ||
            num == 18 ||
            num == 19 ||
            num == 21 ||
            num == 23 ||
            num == 25 ||
            num == 27 ||
            num == 30 ||
            num == 32 ||
            num == 34 ||
            num == 36);
    }

    /// @dev Sentinel `targetNumber` for LIGHTNING_DOUBLE meaning "any number".
    uint8 internal constant ANY_NUMBER = 37;

    function _matchesColor(uint8 num, ISideBet.SideBetColor color) private pure returns (bool) {
        if (color == ISideBet.SideBetColor.RED) return isRed(num);
        // BLACK: any non-zero pocket that is not red (0 is green and matches neither colour).
        return num != 0 && !isRed(num);
    }

    /// @dev Dozen of a pocket: 1 (1-12), 2 (13-24), 3 (25-36); 0 (green) belongs to none.
    function _dozenOf(uint8 num) private pure returns (uint8) {
        if (num == 0) return 0;
        return uint8((num - 1) / 12 + 1);
    }

    /// @dev Column of a pocket: 1, 2 or 3; 0 (green) belongs to none.
    function _columnOf(uint8 num) private pure returns (uint8) {
        if (num == 0) return 0;
        uint8 mod = num % 3;
        return mod == 0 ? 3 : mod;
    }

    /// @param observed Spins seen so far within the window (length <= windowSpins).
    /// @param windowComplete True once `observed.length == windowSpins`.
    /// @param bet Snapshotted bet parameters (betType, color, targets, window).
    /// @return decided Whether the bet can be settled now.
    /// @return won Whether the player won (only meaningful when `decided`).
    function evaluate(
        uint8[] memory observed,
        bool windowComplete,
        ISideBet.Bet memory bet
    ) internal pure returns (bool decided, bool won) {
        if (bet.betType == ISideBet.SideBetType.NUMBER_HIT) {
            uint256 hits;
            for (uint256 i; i < observed.length; ++i) {
                if (observed[i] == bet.targetNumber) ++hits;
            }
            if (hits >= bet.targetCount) return (true, true);
            return (windowComplete, false);
        }

        if (bet.betType == ISideBet.SideBetType.COLOR_COUNT) {
            uint256 count;
            for (uint256 i; i < observed.length; ++i) {
                if (_matchesColor(observed[i], bet.color)) ++count;
            }
            if (count >= bet.targetCount) return (true, true);
            return (windowComplete, false);
        }

        if (bet.betType == ISideBet.SideBetType.CONSECUTIVE_STREAK) {
            uint256 run;
            for (uint256 i; i < observed.length; ++i) {
                if (_matchesColor(observed[i], bet.color)) {
                    unchecked {
                        ++run;
                    }
                    if (run >= bet.targetCount) return (true, true);
                } else {
                    run = 0;
                }
            }
            return (windowComplete, false);
        }

        if (bet.betType == ISideBet.SideBetType.LIGHTNING_DOUBLE) {
            // Same number on `targetCount` consecutive spins (targetNumber == 37 -> any number).
            bool any = bet.targetNumber == ANY_NUMBER;
            uint256 run;
            uint8 n;
            for (uint256 i; i < observed.length; ++i) {
                n = observed[i];
                bool valueOk = any || n == bet.targetNumber;
                if (i > 0 && n == observed[i - 1] && valueOk) {
                    unchecked {
                        ++run;
                    }
                } else if (valueOk) {
                    run = 1;
                } else {
                    run = 0;
                }
                if (run >= bet.targetCount) return (true, true);
            }
            return (windowComplete, false);
        }

        if (bet.betType == ISideBet.SideBetType.PERFECT_ALTERNATION) {
            // Colors strictly alternate across the full window; a 0 or same-colour pair fails it.
            uint8 n;
            for (uint256 i; i < observed.length; ++i) {
                n = observed[i];
                if (n == 0) return (true, false);
                if (i > 0 && isRed(n) == isRed(observed[i - 1])) return (true, false);
            }
            if (windowComplete) return (true, true);
            return (false, false);
        }

        if (bet.betType == ISideBet.SideBetType.DOZEN_HIT || bet.betType == ISideBet.SideBetType.COLUMN_HIT) {
            bool isDozen = bet.betType == ISideBet.SideBetType.DOZEN_HIT;
            uint256 count;
            uint8 group;
            for (uint256 i; i < observed.length; ++i) {
                group = isDozen ? _dozenOf(observed[i]) : _columnOf(observed[i]);
                if (group == bet.targetNumber) ++count;
            }
            if (count >= bet.targetCount) return (true, true);
            uint256 remainingGroup = uint256(bet.windowSpins) - observed.length;
            if (count + remainingGroup < bet.targetCount) return (true, false);
            return (windowComplete, false);
        }

        // RED_RATIO: win if reds make up at least `redRatioBps` of the full window.
        uint256 requiredReds = (uint256(bet.redRatioBps) * bet.windowSpins + (BPS_DENOMINATOR - 1)) / BPS_DENOMINATOR;
        uint256 reds;
        for (uint256 i; i < observed.length; ++i) {
            if (isRed(observed[i])) ++reds;
        }
        if (reds >= requiredReds) return (true, true);
        uint256 remaining = uint256(bet.windowSpins) - observed.length;
        if (reds + remaining < requiredReds) return (true, false);
        return (windowComplete, false);
    }
}

contracts/interfaces/ISideBet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { IBankVault } from "./IBankVault.sol";

/// @title ISideBet — single-player side bets resolved over a window of global roulette rounds.
/// @notice Stakes and payouts use each market's `BankVault4626` LP pool. Outcomes are read from `RouletteEngine`.
interface ISideBet {
    /// @dev Order MUST match the subgraph `SideBetType` enum (schema.graphql).
    enum SideBetType {
        COLOR_COUNT,
        NUMBER_HIT,
        CONSECUTIVE_STREAK,
        RED_RATIO,
        LIGHTNING_DOUBLE,
        PERFECT_ALTERNATION,
        DOZEN_HIT,
        COLUMN_HIT,
        JACKPOT_IN_WINDOW,
        DOZEN_PASSPORT,
        BOOMERANG,
        MIRROR_PAIR,
        WHEEL_NEIGHBORS,
        DISTINCT_COLLECTION,
        COLOR_DUEL,
        FIRST_RETURN,
        COLOR_MIRROR,
        STRICT_ASCENT,
        SUM_RANGE,
        COLOR_MAJORITY,
        EXACT_DOZEN,
        ANY_REPEAT,
        ZIGZAG,
        ANY_DOZEN,
        PHOTO_FINISH
    }

    enum SideBetColor {
        RED,
        BLACK
    }

    enum SideBetStatus {
        ACTIVE,
        WON,
        LOST,
        EXPIRED,
        CANCELLED
    }

    struct SideBetConfig {
        uint32 marketId;
        SideBetType betType;
        SideBetColor color;
        uint8 targetNumber;
        uint16 targetCount;
        uint16 redRatioBps;
        uint16 windowSpins;
        uint32 multiplierBps;
        uint256 minStake;
        uint256 maxStake;
    }

    struct Bet {
        address player;
        uint32 marketId;
        uint256 stake;
        uint256 payout;
        uint64 startGlobalRound;
        uint16 windowSpins;
        SideBetType betType;
        SideBetColor color;
        uint8 targetNumber;
        uint16 targetCount;
        uint16 redRatioBps;
        SideBetStatus status;
        uint64 placedAt;
        uint64 resolvedAt;
    }

    /// @dev Outcome row built in `previewSettleBundleV2` during Automation `checkUpkeep`; applied in `settleBatchV2`.
    /// @param payoutAmount Player payout when `won`; zero when lost.
    /// @dev Original deployed scheduler wire format. Never append fields to this tuple.
    struct LegacySettleRow {
        uint256 betId;
        bool won;
        uint256 payoutAmount;
    }

    struct SettleRow {
        uint256 betId;
        bool won;
        uint256 payoutAmount;
        /// @dev Settled as `EXPIRED` (stake refunded) rather than won/lost. A side bet can only be
        /// decided once enough global rounds have been fulfilled, and rounds only advance when
        /// someone places a *roulette* bet — so in a quiet market a bet is otherwise undecidable
        /// forever, which would block its lane's cursor permanently.
        bool expired;
    }

    /// @dev Per-vault apply bundle built in `previewSettleBundleV2`; passed through Automation `performData`.
    struct SettleVaultApply {
        address bank;
        uint32 marketId;
        uint256 releaseTotal;
        uint256 totalStakes;
        uint256 totalPaid;
        IBankVault.Payout[] winnerPayouts;
    }

    event ConfigAdded(uint256 configId, uint32 marketId, SideBetType betType);
    event ConfigUpdated(uint256 configId);
    event ConfigRemoved(uint256 configId);
    event ConfigStakeLimitsUpdated(uint256 configId, uint256 minStake, uint256 maxStake);
    event MultiplierBandUpdated(uint32 minMultiplierBps, uint32 maxMultiplierBps);
    event SettleTimeoutUpdated(uint64 settleTimeout);
    event SideBetPlaced(
        uint256 betId,
        address player,
        uint256 configId,
        uint32 marketId,
        uint256 stake,
        uint256 payout,
        uint64 startGlobalRound,
        uint16 windowSpins
    );
    event SideBetSettled(uint256 betId, address player, SideBetStatus outcome, uint256 payout);
    event SideBetJackpotFunded(uint32 marketId, uint256 amount);
    event SideBetInfrastructureFeePaid(uint32 marketId, uint256 amount);

    error ZeroAddress();
    error ZeroAmount();
    error InvalidNumber();
    error InvalidConfig();
    error UnknownConfig();
    error ConfigInactive();
    error UnknownMarket();
    error StakeOutOfRange();
    error StakeLimitsNotSet();
    error InsufficientVaultLiquidity();
    error NotResolvableYet();
    error AlreadyResolved();
    error MultiplierOutOfBand();
    /// @dev The start round's VRF is already fulfilled, so its outcome is public — betting on it is closed.
    error RoundOutcomeAlreadyKnown();
    /// @dev Reserved-liquidity accounting is incremental, so it can only be adopted by a proxy that
    ///      holds no bets yet. Adopting it later would under-report `reservedOf` forever, silently.
    error ReservedAccountingMigrationUnsafe();

    function addConfig(SideBetConfig calldata cfg) external returns (uint256 configId);
    function updateConfig(uint256 configId, SideBetConfig calldata cfg) external;
    function removeConfig(uint256 configId) external;
    function setConfigStakeLimits(uint256 configId, uint256 minStake, uint256 maxStake) external;
    function isConfigActive(uint256 configId) external view returns (bool active);
    function placeBet(uint256 configId, uint256 stake) external returns (uint256 betId);
    /// @notice Compatibility endpoint for the deployed three-field scheduler.
    function previewSettleBundle(uint256 cursorBetId, uint32 maxBets, uint32 lane, uint32 laneCount)
        external view returns (LegacySettleRow[] memory rows, uint256 nextCursorBetId, SettleVaultApply[] memory vaultApplies);
    /// @notice Resolve the original report format using current on-chain outcomes and expiry.
    function settleBatch(LegacySettleRow[] calldata rows, SettleVaultApply[] calldata vaultApplies)
        external returns (uint256 settled);
    /// @notice Simulation-only bundle for one automation lane (`betId % laneCount == lane`).
    function previewSettleBundleV2(uint256 cursorBetId, uint32 maxBets, uint32 lane, uint32 laneCount)
        external
        view
        returns (SettleRow[] memory rows, uint256 nextCursorBetId, SettleVaultApply[] memory vaultApplies);
    /// @notice Apply-only: bet rows + pre-built vault bundles from `previewSettleBundleV2` (trusted scheduler + DON).
    function settleBatchV2(SettleRow[] calldata rows, SettleVaultApply[] calldata vaultApplies) external returns (uint256 settled);

    function getBet(uint256 betId) external view returns (Bet memory);
    function getConfig(uint256 configId) external view returns (SideBetConfig memory);
    function configCount() external view returns (uint256);
    function betCount() external view returns (uint256);
    function reservedOf(uint32 marketId) external view returns (uint256);
    function availableVaultLiquidity(uint32 marketId) external view returns (uint256);
    function playerBetCount(address player) external view returns (uint256);
    function playerBetAt(address player, uint256 index) external view returns (uint256 betId);
    function isResolvable(uint256 betId) external view returns (bool);
}

