contracts/SideBetChallengeEvaluator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;
import {ISideBet} from "./interfaces/ISideBet.sol";
import {SideBetChallengeLib} from "./libraries/SideBetChallengeLib.sol";
import {SideBetOutcomeLib} from "./libraries/SideBetOutcomeLib.sol";
/// @notice Stateless evaluator created with each SideBet implementation; no admin or mutable rules.
contract SideBetChallengeEvaluator {
    /// @dev Ticket-local fee rounding is independent of settlement batching.
    function ticketFees(uint256 stake, uint256 paid, uint256 swapBps) external pure returns (uint256 swap, uint256 infra) {
        if (stake <= paid) return (0, 0);
        uint256 profit = stake - paid;
        return (profit * swapBps / 10000, profit * 200 / 10000);
    }
    /// @notice Immutable stateless validation keeps the upgrade implementation below EIP-170.
    function validConfig(ISideBet.SideBetConfig calldata cfg) external pure returns (bool) {
        if (uint8(cfg.betType) >= uint8(ISideBet.SideBetType.ANY_REPEAT)) {
            if (cfg.windowSpins < 2 || cfg.windowSpins > 64 || cfg.redRatioBps != 0) return false;
            if (cfg.betType == ISideBet.SideBetType.PHOTO_FINISH) return cfg.targetNumber <= 36 && cfg.targetCount == 0;
            if (cfg.targetNumber != 0) return false;
            if (cfg.betType == ISideBet.SideBetType.ANY_DOZEN) return cfg.windowSpins <= 16 && cfg.targetCount >= 2 && cfg.targetCount <= cfg.windowSpins;
            if (cfg.targetCount != 0) return false;
            return cfg.betType == ISideBet.SideBetType.ZIGZAG ? cfg.windowSpins == 4 : cfg.windowSpins <= 16;
        }
        if (uint8(cfg.betType) >= uint8(ISideBet.SideBetType.FIRST_RETURN)) {
            if (cfg.windowSpins < 2 || cfg.windowSpins > 64) return false;
            if (cfg.betType == ISideBet.SideBetType.SUM_RANGE) {
                // Inclusive bounds: targetNumber = lower, redRatioBps = upper (not a ratio).
                if (cfg.windowSpins != 3 || cfg.targetCount != 0 || cfg.targetNumber > cfg.redRatioBps || cfg.redRatioBps > 108 || (cfg.targetNumber == 0 && cfg.redRatioBps == 108)) return false;
            } else if (cfg.betType == ISideBet.SideBetType.EXACT_DOZEN) {
                if (cfg.targetNumber < 1 || cfg.targetNumber > 3 || cfg.targetCount > cfg.windowSpins || cfg.redRatioBps != 0) return false;
            } else {
                if (cfg.targetNumber != 0 || cfg.targetCount != 0 || cfg.redRatioBps != 0) return false;
                if (cfg.betType == ISideBet.SideBetType.COLOR_MIRROR && cfg.windowSpins != 4) return false;
                if (cfg.betType == ISideBet.SideBetType.STRICT_ASCENT && cfg.windowSpins != 3) return false;
            }
        } else if (uint8(cfg.betType) >= uint8(ISideBet.SideBetType.DOZEN_PASSPORT)) {
            // Bound per-ticket evaluation cost for the new challenge families.
            if (cfg.windowSpins > 64 || cfg.targetNumber != 0 || cfg.redRatioBps != 0) return false;
            if (cfg.betType == ISideBet.SideBetType.DOZEN_PASSPORT) {
                if (cfg.windowSpins < 3 || cfg.targetCount != 3) return false;
            } else if (cfg.betType == ISideBet.SideBetType.DISTINCT_COLLECTION) {
                if (cfg.targetCount < 2 || cfg.targetCount > 37 || cfg.targetCount > cfg.windowSpins) return false;
            } else if (cfg.betType == ISideBet.SideBetType.COLOR_DUEL) {
                if (cfg.targetCount < 1 || cfg.targetCount > cfg.windowSpins) return false;
            } else {
                if (cfg.targetCount != 0 || cfg.windowSpins < (cfg.betType == ISideBet.SideBetType.BOOMERANG ? 3 : 2)) return false;
            }

        }
        else if (cfg.betType == ISideBet.SideBetType.NUMBER_HIT) {
            return cfg.targetNumber <= 36 && cfg.targetCount > 0 && cfg.targetCount <= cfg.windowSpins;
        } else if (cfg.betType == ISideBet.SideBetType.COLOR_COUNT || cfg.betType == ISideBet.SideBetType.CONSECUTIVE_STREAK) {
            return cfg.targetCount > 0 && cfg.targetCount <= cfg.windowSpins;
        } else if (cfg.betType == ISideBet.SideBetType.RED_RATIO) {
            return cfg.redRatioBps > 0 && cfg.redRatioBps <= 10000;
        } else if (cfg.betType == ISideBet.SideBetType.LIGHTNING_DOUBLE) {
            return cfg.targetNumber <= 37 && cfg.targetCount >= 2 && cfg.targetCount <= cfg.windowSpins;
        } else if (cfg.betType == ISideBet.SideBetType.PERFECT_ALTERNATION) {
            return cfg.windowSpins >= 2;
        } else if (cfg.betType != ISideBet.SideBetType.JACKPOT_IN_WINDOW) {
            return cfg.targetNumber >= 1 && cfg.targetNumber <= 3 && cfg.targetCount > 0 && cfg.targetCount <= cfg.windowSpins;
        }
        return true;
    }
    function evaluate(uint8[] memory nums, bool complete, ISideBet.Bet memory bet) external pure returns (bool, bool) {
        if (uint8(bet.betType) >= uint8(ISideBet.SideBetType.DOZEN_PASSPORT)) {
            return SideBetChallengeLib.evaluateChallenge(nums, complete, bet);
        }
        return SideBetOutcomeLib.evaluate(nums, complete, bet);
    }
}

contracts/libraries/SideBetChallengeLib..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;
import {ISideBet} from "../interfaces/ISideBet.sol";
import {SideBetOutcomeLib} from "./SideBetOutcomeLib.sol";
library SideBetChallengeLib {
    function _dozenOf(uint8 n) private pure returns (uint8) {
        return n == 0 ? 0 : (n - 1) / 12 + 1;
    }
    function _matchesColor(uint8 n, ISideBet.SideBetColor c) private pure returns (bool) {
        return c == ISideBet.SideBetColor.RED ? SideBetOutcomeLib.isRed(n) : (n != 0 && !SideBetOutcomeLib.isRed(n));
    }
    /// @dev Append-only enum extension: existing nine families and storage layout are unchanged.
    function evaluateChallenge(
        uint8[] memory observed,
        bool complete,
        ISideBet.Bet memory bet
    ) internal pure returns (bool decided, bool won) {
        if (uint8(bet.betType) >= uint8(ISideBet.SideBetType.ANY_REPEAT)) return evaluateFunky(observed, complete, bet);
        if (uint8(bet.betType) >= uint8(ISideBet.SideBetType.FIRST_RETURN)) return evaluateWindow(observed, complete, bet);
        uint256 mask;
        uint256 collected;
        uint256 own;
        uint256 other;
        for (uint256 i; i < observed.length; ++i) {
            uint8 n = observed[i];
            if (
                bet.betType == ISideBet.SideBetType.DOZEN_PASSPORT ||
                bet.betType == ISideBet.SideBetType.DISTINCT_COLLECTION
            ) {
                if (bet.betType == ISideBet.SideBetType.DOZEN_PASSPORT && n == 0) continue;
                uint256 bit = uint256(1) << (bet.betType == ISideBet.SideBetType.DOZEN_PASSPORT ? _dozenOf(n) : n);
                if (mask & bit == 0) {
                    mask |= bit;
                    ++collected;
                }
                if (collected >= bet.targetCount) return (true, true);
            } else if (bet.betType == ISideBet.SideBetType.COLOR_DUEL) {
                if (n == 0) continue;
                if (_matchesColor(n, bet.color)) {
                    if (++own >= bet.targetCount) return (true, true);
                } else {
                    if (++other >= bet.targetCount) return (true, false);
                }
            } else if (bet.betType == ISideBet.SideBetType.BOOMERANG) {
                if (i >= 2 && n == observed[i - 2] && n != observed[i - 1]) return (true, true);
            } else if (i > 0) {
                if (bet.betType == ISideBet.SideBetType.MIRROR_PAIR && uint256(n) + observed[i - 1] == 36)
                    return (true, true);
                if (bet.betType == ISideBet.SideBetType.WHEEL_NEIGHBORS && adjacent(n, observed[i - 1]))
                    return (true, true);
            }
        }
        return (complete, false);
    }

    /// @dev Full-window families never accept a different or replacement round window.
    function evaluateWindow(uint8[] memory nums, bool complete, ISideBet.Bet memory b) private pure returns (bool, bool) {
        if (nums.length > b.windowSpins) return (false, false);
        uint256 count;
        uint256 other;
        uint256 sum;
        bool returned;
        bool broken;
        for (uint256 i; i < nums.length; ++i) {
            uint8 n = nums[i];
            if (n > 36) return (false, false);
            sum += n;
            if (i > 0 && n == nums[0]) returned = true;
            if (b.betType == ISideBet.SideBetType.STRICT_ASCENT && i > 0 && n <= nums[i-1]) broken = true;
            if (b.betType == ISideBet.SideBetType.COLOR_MIRROR) {
                if (n == 0) broken = true;
                if (i == 1 && SideBetOutcomeLib.isRed(n) == SideBetOutcomeLib.isRed(nums[0])) broken = true;
                if (i == 2 && SideBetOutcomeLib.isRed(n) != SideBetOutcomeLib.isRed(nums[1])) broken = true;
                if (i == 3 && SideBetOutcomeLib.isRed(n) != SideBetOutcomeLib.isRed(nums[0])) broken = true;
            }
            if (b.betType == ISideBet.SideBetType.EXACT_DOZEN && n != 0 && _dozenOf(n) == b.targetNumber) ++count;
            if (b.betType == ISideBet.SideBetType.COLOR_MAJORITY && n != 0) {
                if (_matchesColor(n,b.color)) ++count; else ++other;
            }
        }
        // Except first-return, keep settlement at the end even if the UI can explain impossibility.
        if (b.betType == ISideBet.SideBetType.FIRST_RETURN && returned) return (true, true);
        if (!complete || nums.length != b.windowSpins) return (false, false);
        if (b.betType == ISideBet.SideBetType.FIRST_RETURN) return (true, false);
        if (b.betType == ISideBet.SideBetType.COLOR_MIRROR || b.betType == ISideBet.SideBetType.STRICT_ASCENT) return (true, !broken);
        if (b.betType == ISideBet.SideBetType.SUM_RANGE) return (true, sum >= b.targetNumber && sum <= b.redRatioBps);
        if (b.betType == ISideBet.SideBetType.COLOR_MAJORITY) return (true, count > other);
        if (b.betType == ISideBet.SideBetType.EXACT_DOZEN) return (true, count == b.targetCount);
        return (false, false);
    }

    /// @dev Fixed consecutive window; early wins only for duplicate/any-dozen conditions.
    function evaluateFunky(uint8[] memory nums, bool complete, ISideBet.Bet memory b) private pure returns (bool, bool) {
        if (nums.length > b.windowSpins) return (false, false);
        for (uint256 i; i < nums.length; ++i) if (nums[i] > 36) return (false, false);
        uint256 mask;
        uint256[3] memory dozens;
        bool broken;
        for (uint256 i; i < nums.length; ++i) {
            uint8 n = nums[i];
            if (b.betType == ISideBet.SideBetType.ANY_REPEAT) {
                uint256 bit = uint256(1) << n;
                if (mask & bit != 0) return (true, true);
                mask |= bit;
            } else if (b.betType == ISideBet.SideBetType.ANY_DOZEN && n != 0) {
                if (++dozens[_dozenOf(n) - 1] >= b.targetCount) return (true, true);
            } else if (b.betType == ISideBet.SideBetType.ZIGZAG && i > 0) {
                if (n == nums[i-1] || (i > 1 && (n > nums[i-1]) == (nums[i-1] > nums[i-2]))) broken = true;
            } else if (b.betType == ISideBet.SideBetType.PHOTO_FINISH && i + 1 < b.windowSpins && n == b.targetNumber) {
                broken = true;
            }
        }
        if (!complete || nums.length != b.windowSpins) return (false, false);
        if (b.betType == ISideBet.SideBetType.ZIGZAG) return (true, !broken);
        if (b.betType == ISideBet.SideBetType.PHOTO_FINISH) return (true, !broken && nums[nums.length - 1] == b.targetNumber);
        return (true, false);
    }

    function adjacent(uint8 a, uint8 b) private pure returns (bool) {
        // European wheel, clockwise from zero. Includes wraparound 26 <-> 0.
        bytes memory wheel = hex"00200f13041502191122061b0d240b1e08170a0518102101140e1f0916121d071c0c23031a";
        for (uint256 i; i < 37; ++i)
            if (uint8(wheel[i]) == a) return uint8(wheel[(i + 1) % 37]) == b || uint8(wheel[(i + 36) % 37]) == b;
        return false;
    }
}

